INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(96942, 'ruRU', '', 'Мне жаль слышать, что Ардуэн не выжил. Я прослежу, чтобы демоны заплатили за его смерть.', 24330),
(96947, 'ruRU', '', 'Смотри, чтобы так и было.', 24330),
(96991, 'ruRU', '', 'Нам нужно его вернуть. Он всё ещё под моей опекой. Придётся штурмовать башню. Но лёгкой задачей это не будет.', 24330),
(96992, 'ruRU', '', 'Защитник, пока что вернись к своим прочим обязанностям. Скоро нам предстоит столкнуться с самим лордом Вороньей Скалой.', 24330),
(96997, 'ruRU', '', 'Спасибо, герой. Я не ожидал спасения из этого места. Где мой брат?', 24330),
(97007, 'ruRU', '', 'Лейтенант Звёздный Глаз командует. Смерть всем незваным гостям!', 24330),
(97013, 'ruRU', '', 'Сюда! Эта канализация выведет нас обратно наружу. Нужно идти, пока враги не перегруппировались.', 24330),
(97015, 'ruRU', '', 'Битва бушует по всему Танаану, командир. На чём нам сосредоточить внимание сегодня?', 24330),
(97016, 'ruRU', '', 'Гул''дан создаёт собственную армию фанатиков. Куда нам нанести ответный удар?', 24330),
(97017, 'ruRU', '', 'Гул''дан нас не сломит. Легион НИКОГДА нас не сломит! Сегодня мы даём отпор.', 24330),
(97018, 'ruRU', '', 'Эти джунгли таят неисчислимые опасности. Но если мы будем мудры, мы сможем использовать их, чтобы скрыть нашу следующую атаку.', 24330),
(97019, 'ruRU', '', 'У меня здесь последние донесения от рангари, командир. Куда нам нанести удар?', 24330),
(97020, 'ruRU', '', 'Прислужники Скверны Гул''дана сжимают кольцо вокруг нас. Мы ДОЛЖНЫ перейти в наступление, командир!', 24330),
(97021, 'ruRU', '', 'Наши воины благословлены светом, уверены в своей цели и закалены битвами. Они ждут твоих приказов.', 24330),
(97022, 'ruRU', '', 'Если это действительно конец света, то я, по крайней мере, встречу его в бою. За Самару, за Маараада, за всех тех, кто отдал свои жизни, чтобы подарить нам этот день!', 24330),
(97070, 'ruRU', '', 'Это, пожалуй, лучший день в моей жизни!', 24330),
(97073, 'ruRU', '', 'Ничто не сравнится с азартом охоты на существо в десять раз больше тебя!', 24330),
(97074, 'ruRU', '', 'Может, сделаем С.Е.Л.Ф.И.?', 24330),
(97075, 'ruRU', '', 'К следующему!', 24330),
(97078, 'ruRU', '', 'Я чувствую себя немного увереннее со своим ружьём.', 24330),
(97081, 'ruRU', '', 'Мы ведь туда не пойдём, да?', 24330),
(97120, 'ruRU', '', 'Этот, к сожалению, живуч. Готов, когда скажешь.', 24330),
(97128, 'ruRU', '', 'Дай мне перевести дух, герой. Долгие годы бдения дали о себе знать.', 24330),
(97130, 'ruRU', '', 'Чёрт! Да мы тут как на ладони!', 24330),
(97131, 'ruRU', '', 'Покажитесь, трусы...', 24330),
(97133, 'ruRU', '', 'Ещё чужаки в моём небе?! Умри!', 24330),
(97153, 'ruRU', '', 'Я рад видеть, что мои собратья в безопасности. Сатиры побеждены, но, боюсь, наша борьба только начинается.$B$BЕсли то, что они сказали, правда, то наше бдение в Изумрудном Сне должно продолжаться, и даже с ещё большей неотложностью, чем прежде.', 24330),
(97154, 'ruRU', '', 'Я увидел знаки рано, но был заперт внутри сна. Если бы только я предупредил их раньше!', 24330),
(97171, 'ruRU', '', 'Укротитель нетопырей Алзизек призывает Визжащего нетопыря Скверны, чтобы сплотить поблизости силы Легиона!', 24330),
(97172, 'ruRU', '', 'Назойливый ворген, тебе стоило позволить пламени забрать себя.', 24330),
(97176, 'ruRU', '', 'Наслаждайся последними мгновениями, пока мой яд разрушает тебя изнутри. Мне отрадно знать, как сильно ты будешь страдать.', 24330),
(97177, 'ruRU', '', 'Покинем это место, $c.', 24330),
(97184, 'ruRU', '', 'Изера атакует Храм Элуны!$b$bНужно остановить её, пока храм не разрушен полностью... у нас мало времени!', 24330),
(97205, 'ruRU', '', 'КТО ПОСМЕЛ ТРОГАТЬ МОЮ КНИГУ?', 24330),
(97206, 'ruRU', '', 'ЕЁ СЕКРЕТЫ НЕ ДЛЯ ВАС, СМЕРТНЫЕ!', 24330),
(97207, 'ruRU', '', 'ТЫ ЗАПЛАТИШЬ ЗА СВОЮ ДЕРЗОСТЬ! ВЕСЬ ЭТОТ ГОРОД СГОРИТ!', 24330),
(97211, 'ruRU', '', 'ТЫ СНОВА ВОРУЕШЬ У ВРАЙКУЛОВ, ЧУЖЕЗЕМЕЦ!', 24330),
(97212, 'ruRU', '', 'МОЙ ФОЛИАНТ ХРАНИТ МУДРОСТЬ, СОБРАННУЮ ЗА ТЫСЯЧУ ЖИЗНЕЙ!', 24330),
(97213, 'ruRU', '', 'ИСКУПИ СВОИ ПРЕСТУПЛЕНИЯ! ВЕРНИ КНИГУ МОЕМУ НАРОДУ!', 24330),
(97214, 'ruRU', '', 'ПРОДОЛЖИШЬ РАСХИЩАТЬ ЕЁ СЕКРЕТЫ — И ПОПЛАТИШЬСЯ ЖИЗНЬЮ!', 24330);
